tool_calls:
mkdir -p /reports
awk '
BEGIN { total=0; passed=0; failed=0 }
/^PASS[[:space:]]+/ { total++; passed++; next }
/^FAIL[[:space:]]+/ { total++; failed++; failures[++n]=$2 }
END {
  print "# Test Summary"
  printf "Total: %d | Passed: %d | Failed: %d\n\n", total, passed, failed
  print "## Failures"
  for (i=1; i<=n; i++) print "- " failures[i]
}' /data/test-results.txt | tee /reports/test-summary.md

